using System;
using System.Diagnostics;
using System.Drawing;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace EasyRetro {
 internal sealed class MainForm:Form {
  readonly Label current=new Label();readonly Button restore=new Button();readonly TableLayoutPanel cards=new TableLayoutPanel();
  public MainForm(){Text="EasyRetro";Font=new Font("Malgun Gothic",10);AutoScaleMode=AutoScaleMode.Dpi;ClientSize=new Size(900,620);MinimumSize=new Size(800,610);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(247,248,250);Padding=new Padding(30);
   TableLayoutPanel layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,58));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,38));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,40));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,57));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,42));Controls.Add(layout);
   Label title=new Label{Text="익숙한 그 시절, 새로운 시작",Font=new Font("Malgun Gothic",23,FontStyle.Bold),Dock=DockStyle.Fill,ForeColor=Color.FromArgb(27,40,58)};layout.Controls.Add(title,0,0);current.Dock=DockStyle.Fill;current.ForeColor=Color.FromArgb(83,96,113);layout.Controls.Add(current,0,1);
   layout.Controls.Add(new Label{Text="Windows 11 탐색기 탭 · 작업표시줄 묶기 · 검색 유지 (Shift+Win: 기본 시작)",Dock=DockStyle.Fill,ForeColor=Color.FromArgb(47,80,115)},0,2);
   cards.Dock=DockStyle.Fill;cards.ColumnCount=2;cards.RowCount=1;cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));layout.Controls.Add(cards,0,3);AddCard("98","Windows 98","청록 배경, 클래식 회색, 간결한 시작메뉴");AddCard("xp","Windows XP","푸른 하늘, 초록 언덕, 생동감 있는 시작메뉴");
   restore.Text="원래대로 복구";restore.Width=180;restore.Height=38;restore.FlatStyle=FlatStyle.Flat;restore.Anchor=AnchorStyles.Right;restore.Click+=delegate{Run("--restore",null);};layout.Controls.Add(restore,0,4);
   layout.Controls.Add(new Label{Text="적용 시 관리자 권한 및 인터넷이 필요합니다. ExplorerPatcher · Open-Shell이 자동 설치됩니다.",Dock=DockStyle.Fill,ForeColor=Color.DimGray,Font=new Font("Malgun Gothic",9)},0,5);RefreshState();
  }
  void AddCard(string id,string heading,string description){Panel card=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Margin=new Padding(id=="98"?0:10,0,id=="98"?10:0,6),Padding=new Padding(14),BorderStyle=BorderStyle.FixedSingle};TableLayoutPanel inner=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4};inner.RowStyles.Add(new RowStyle(SizeType.Percent,100));inner.RowStyles.Add(new RowStyle(SizeType.Absolute,38));inner.RowStyles.Add(new RowStyle(SizeType.Absolute,33));inner.RowStyles.Add(new RowStyle(SizeType.Absolute,46));card.Controls.Add(inner);PictureBox picture=new PictureBox{Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom,Image=AssetGenerator.Preview(ThemeSpec.Get(id)),Cursor=Cursors.Hand,AccessibleName=heading+" 미리보기"};picture.Click+=delegate{Run("--apply",id);};picture.Disposed+=delegate{picture.Image.Dispose();};inner.Controls.Add(picture,0,0);inner.Controls.Add(new Label{Text=heading,Dock=DockStyle.Fill,TextAlign=ContentAlignment.BottomLeft,Font=new Font("Malgun Gothic",16,FontStyle.Bold)},0,1);inner.Controls.Add(new Label{Text=description,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,Font=new Font("Malgun Gothic",9),ForeColor=Color.DimGray},0,2);Button apply=new Button{Text=heading+" 적용",Dock=DockStyle.Fill,FlatStyle=FlatStyle.Flat,BackColor=id=="xp"?Color.FromArgb(33,99,196):Color.FromArgb(38,96,100),ForeColor=Color.White};apply.FlatAppearance.BorderSize=0;apply.Click+=delegate{Run("--apply",id);};inner.Controls.Add(apply,0,3);cards.Controls.Add(card);}
  void RefreshState(){AppState state=StateStore.Default().Load();current.Text=state==null?"테마를 선택하면 한 번에 적용합니다. 원래 설정은 첫 적용 전에 보관합니다.":"EasyRetro 매니저 · 현재 테마: "+(state.appliedTheme=="xp"?"Windows XP":state.appliedTheme=="98"?"Windows 98":"복구 필요")+(state.operation=="applied"?"":" · 중단된 작업이 있습니다. 먼저 복구하세요.");restore.Visible=state!=null;}
  async void Run(string action,string theme){Enabled=false;try{int code=await Task.Run(delegate{return Program.Elevate(action,theme);});RefreshState();if(code!=0)MessageBox.Show(this,"작업을 완료하지 못했습니다. 진행창의 안내와 로그를 확인하세요.","EasyRetro",MessageBoxButtons.OK,MessageBoxIcon.Warning);}catch(System.ComponentModel.Win32Exception e){if(e.NativeErrorCode!=1223)MessageBox.Show(this,e.Message,"EasyRetro");}catch(Exception e){MessageBox.Show(this,e.Message,"EasyRetro");}finally{Enabled=true;Activate();}}
 }
}
